/**
 * Upload file buffers to Rayvn /files endpoint.
 *
 * Fetches buffers from global context using context_key from msg.entry.files.
 * Uploads each file to Rayvn and collects returned file IDs.
 * Failed uploads are added to entry.failed_files.
 *
 * On completion:
 *   - payload.files is replaced with an array of Rayvn file IDs
 *   - entry.failed_files is updated with any upload failures
 */
const target   = msg.metadata.target;
const baseUrl  = global.get("parat_bridge").base_urls.rayvn;
const utils    = global.get("utils");
const files    = (msg.entry && msg.entry.files) || [];

// Safety net: if no files, pass through
if (files.length === 0) {
    msg.payload.files = [];
    return msg;
}

const resolved = [];
const failed   = [];

for (const file of files) {
    if (!file.context_key) continue;

    const buffer = global.get("files." + file.context_key);

    if (!buffer || buffer.length === 0) {
        node.warn("No buffer found for context_key: " + file.context_key);
        failed.push({ name: file.name || "ukjent fil", reason: utils.FILE_REASONS.UPLOAD_FAILED });
        continue;
    }

    try {
        const boundary = "----PBBoundary" + Date.now();
        const header   = `--${boundary}\r\nContent-Disposition: form-data; name="file"; filename="${file.name || "file.bin"}"\r\nContent-Type: ${file.type || "application/octet-stream"}\r\n\r\n`;
        const footer   = `\r\n--${boundary}--\r\n`;
        const body     = Buffer.concat([Buffer.from(header), buffer, Buffer.from(footer)]);

        const res = await nodeFetch(baseUrl + "/files", {
            method:  "POST",
            headers: {
                "Authorization": "Bearer " + target.api_key,
                "Content-Type":  "multipart/form-data; boundary=" + boundary
            },
            body
        });

        if (res.ok) {
            const data = await res.json();
            resolved.push(data.id);
            node.log(`File uploaded: ${file.name} → ${data.id}`);
        } else {
            node.warn(`Rayvn /files returned ${res.status} for ${file.name}`);
            failed.push({ name: file.name || "ukjent fil", reason: utils.FILE_REASONS.UPLOAD_FAILED });
        }
    } catch (e) {
        node.warn(`Error uploading ${file.name}: ${e.message}`);
        failed.push({ name: file.name || "ukjent fil", reason: utils.FILE_REASONS.UPLOAD_FAILED });
    }
}

msg.payload.files = resolved;

// Merge upload failures into entry.failed_files
if (failed.length > 0 && msg.entry) {
    msg.entry.failed_files = [
        ...(msg.entry.failed_files || []),
        ...failed
    ];
}

return msg;

const target = msg.metadata.target;

if (!target || !target.api_key || !target.client_specific.log_id) {
    node.error("Rayvn not configured on this connection");
    return null;
}

msg.url = global.get("parat_bridge").base_urls.rayvn
    + "/logs/" + target.client_specific.log_id + "/entry";

msg.headers = {
    "Authorization": "Bearer " + target.api_key,
    "Content-Type":  "application/json",
    "Accept":        "application/json"
};

return msg;

msg.topic = "response"

if (msg.statusCode == 200) {
    msg.result = true
} else {
    msg.result = false
}

return msg;

/**
 * Build notification if any files failed during Rayvn upload.
 * Reads from entry.failed_files which may contain both GET-side
 * and upload failures at this point.
 *
 * Output 1: msg continues (always)
 * Output 2: notification payload (only on upload failures)
 */
const entry  = msg.entry;
const failed = (entry && entry.failed_files) || [];

const upload_failed = failed.filter(f => f.reason === "upload_failed");

if (upload_failed.length === 0) return [msg, null];

const notification = {
    payload: {
        entry_id:     entry.id,
        failed_files: upload_failed,
        total_files:  (entry.files || []).length + failed.length,
        succeeded:    (entry.files || []).length,
        entry_author: entry.author,
        metadata:     msg.metadata
    }
};

return [msg, notification];
